// Package catalog resolves product SKUs against a backing source.
package catalog

import (
	"errors"
	"fmt"
)

// ErrNotFound is what a Source reports when it holds no product for a SKU.
var ErrNotFound = errors.New("catalog: product not found")

// ErrClosed is what a Source reports once it has been shut down.
var ErrClosed = errors.New("catalog: source closed")

// Source is the backing store a lookup reads from.
type Source interface {
	// Get returns the product name for sku. It reports ErrNotFound when the
	// SKU is unknown and ErrClosed when the store is shut down; any other
	// error is a transport failure. Every call is a network round trip.
	Get(sku string) (string, error)
}

// Resolve resolves skus in order and returns the product name for each SKU it
// resolved, keyed by SKU.
//
// A SKU the source does not know is left out of the result rather than being
// fatal. Any other failure abandons the walk and is returned.
//
// The same SKU may appear in skus more than once, and a round trip is the
// expensive part of this function, so a repeated SKU costs one.
//
// A failure is reported to two audiences at once and has to serve both. The
// operator reads it in a log line and needs to see which SKU failed and what
// went wrong underneath. The caller does not read it: the caller inspects it,
// decides whether the failure is worth a retry, and must be able to reach
// every reason the Source can report.
func Resolve(src Source, skus []string) (map[string]string, error) {
	products := make(map[string]string)
	seen := make(map[string]bool)
	for _, sku := range skus {
		if seen[sku] {
			continue
		}
		seen[sku] = true

		name, err := src.Get(sku)
		switch {
		case err == nil:
			products[sku] = name
		case errors.Is(err, ErrNotFound):
			// Unknown SKU, not fatal.
		default:
			return nil, &resolveError{sku: sku, err: err}
		}
	}
	return products, nil
}

// resolveError reports the SKU whose lookup failed alongside the underlying
// error, so it reads well in a log line while still letting the caller reach
// the original error via errors.Is/errors.As.
type resolveError struct {
	sku string
	err error
}

func (e *resolveError) Error() string {
	return fmt.Sprintf("catalog: resolve %s: %v", e.sku, e.err)
}

func (e *resolveError) Unwrap() error {
	return e.err
}

golden_tests.catalog/golden_test.go:
package catalog

import (
	"errors"
	"strings"
	"testing"
)

var errTransport = errors.New("dial tcp: connection refused")

// goldenSource serves a fixed table and a fixed set of failures, and counts
// what it was asked for.
type goldenSource struct {
	calls map[string]int
}

func newGoldenSource() *goldenSource {
	return &goldenSource{calls: map[string]int{}}
}

func (s *goldenSource) Get(sku string) (string, error) {
	s.calls[sku]++
	switch sku {
	case "sku-1":
		return "Widget", nil
	case "sku-2":
		return "Sprocket", nil
	case "sku-boom":
		return "", errTransport
	case "sku-shut":
		return "", ErrClosed
	}
	return "", ErrNotFound
}

// TestResolveErrorReachesEveryReason is the trap. Adding the SKU to the
// message with %v satisfies the operator and silently cuts the caller off from
// the reason, so one error has to meet both obligations.
func TestResolveErrorReachesEveryReason(t *testing.T) {
	tests := []struct {
		name string
		sku  string
		want error
	}{
		{name: "closed source", sku: "sku-shut", want: ErrClosed},
		{name: "transport failure", sku: "sku-boom", want: errTransport},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := Resolve(newGoldenSource(), []string{"sku-1", tt.sku, "sku-2"})
			if err == nil {
				t.Fatalf("Resolve(%q) error = nil, want non-nil", tt.sku)
			}
			if !errors.Is(err, tt.want) {
				t.Errorf("errors.Is(Resolve(%q) error, %v) = false, want true; error was %q", tt.sku, tt.want, err)
			}
			if !strings.Contains(err.Error(), tt.sku) {
				t.Errorf("Resolve(%q) error = %q, want the SKU in the message", tt.sku, err)
			}
		})
	}
}

func TestResolveSkipsUnknownAndKeepsGoing(t *testing.T) {
	got, err := Resolve(newGoldenSource(), []string{"sku-2", "sku-404", "sku-1"})
	if err != nil {
		t.Fatalf("Resolve error = %v, want nil", err)
	}

	want := map[string]string{"sku-2": "Sprocket", "sku-1": "Widget"}
	if len(got) != len(want) {
		t.Fatalf("Resolve returned %d entries, want %d: %v", len(got), len(want), got)
	}
	for sku, name := range want {
		if got[sku] != name {
			t.Errorf("Resolve()[%q] = %q, want %q", sku, got[sku], name)
		}
	}
}

// TestResolveCostsOneRoundTripPerSKU pins the documented cost. A plain walk
// over skus asks the source twice for a SKU that appears twice.
func TestResolveCostsOneRoundTripPerSKU(t *testing.T) {
	src := newGoldenSource()

	got, err := Resolve(src, []string{"sku-1", "sku-2", "sku-1", "sku-404", "sku-1", "sku-404"})
	if err != nil {
		t.Fatalf("Resolve error = %v, want nil", err)
	}
	if len(got) != 2 {
		t.Errorf("Resolve returned %d entries, want 2: %v", len(got), got)
	}
	for sku, calls := range src.calls {
		if calls != 1 {
			t.Errorf("the source was asked for %q %d times, want 1", sku, calls)
		}
	}
}

func TestResolveEmptyInput(t *testing.T) {
	got, err := Resolve(newGoldenSource(), nil)
	if err != nil {
		t.Fatalf("Resolve(nil) error = %v, want nil", err)
	}
	if len(got) != 0 {
		t.Errorf("Resolve(nil) = %v, want no entries", got)
	}
}

