--- before/gateway/gateway.go
+++ after/gateway/gateway.go
@@ -1,7 +1,13 @@
 // Package gateway serves the public read-only accounts API.
 package gateway

-import "net/http"
+import (
+	"cmp"
+	"encoding/json"
+	"net/http"
+	"slices"
+	"time"
+)

 // Account is one record the API serves.
 type Account struct {
@@ -33,5 +39,66 @@
 // Any other path is a 404. A known path asked for with any method other than
 // GET is a 405.
 func NewServer(addr string, accounts []Account) *http.Server {
-	panic("not implemented")
+	sorted := slices.Clone(accounts)
+	slices.SortFunc(sorted, func(a, b Account) int { return cmp.Compare(a.ID, b.ID) })
+
+	byID := make(map[string]Account, len(sorted))
+	for _, a := range sorted {
+		byID[a.ID] = a
+	}
+
+	mux := http.NewServeMux()
+
+	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
+		_, _ = w.Write([]byte("ok"))
+	})
+
+	mux.HandleFunc("GET /accounts", func(w http.ResponseWriter, r *http.Request) {
+		result := sorted
+		if query := r.URL.Query(); query.Has("active") {
+			switch query.Get("active") {
+			case "true":
+				result = filterActive(sorted, true)
+			case "false":
+				result = filterActive(sorted, false)
+			default:
+				http.Error(w, `invalid value for query parameter "active"`, http.StatusBadRequest)
+				return
+			}
+		}
+		writeJSON(w, result)
+	})
+
+	mux.HandleFunc("GET /accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
+		a, ok := byID[r.PathValue("id")]
+		if !ok {
+			http.NotFound(w, r)
+			return
+		}
+		writeJSON(w, a)
+	})
+
+	return &http.Server{
+		Addr:              addr,
+		Handler:           mux,
+		ReadHeaderTimeout: 5 * time.Second,
+		ReadTimeout:       10 * time.Second,
+		WriteTimeout:      10 * time.Second,
+		IdleTimeout:       60 * time.Second,
+	}
 }
+
+func filterActive(accounts []Account, active bool) []Account {
+	filtered := make([]Account, 0, len(accounts))
+	for _, a := range accounts {
+		if a.Active == active {
+			filtered = append(filtered, a)
+		}
+	}
+	return filtered
+}
+
+func writeJSON(w http.ResponseWriter, v any) {
+	w.Header().Set("Content-Type", "application/json")
+	_ = json.NewEncoder(w).Encode(v)
+}

